    if (f.Lead && (f.Needs_Human === true || intent === 'not_interested' || intent === 'opt_out' || recent)) hold.add(String(f.Lead));
  }
  const futureBooked = new Set();                             // leads that already have an upcoming appointment
  for (const a of appointments) {
    const f = a.fields || {};
    if (f.Status === 'Booked' && f.Lead && typeof f.Start === 'number' && f.Start * 1000 >= nowMs) futureBooked.add(String(f.Lead));
  }
  const person = (id) => {
    const f = leads[id];
    return {
      lead_row_id: Number(id),
      lead_id: f.Lead_ID || `row ${id}`,
      lead_name: String(f.Name || ''),
      lead_phone: String(f.Phone || ''),
      opted_out: f.Opted_Out === true,
      automation_paused: paused.has(id),
    };
  };
  const push = (json) => out.push({ json: { ...ctx, ...json }, pairedItem: { item: i } });

  // 1. No-show rebook: the newest no-show per patient from the last `lookback` days (not today), Rebook_Sent empty.
  const noShow = {};
  for (const a of appointments) {
    const f = a.fields || {};
    if (f.Status !== 'No-show' || f.Rebook_Sent || !f.Lead || typeof f.Start !== 'number') continue;
    const d = daysAgo(f.Start);
    if (d < 1 || d > lookback) continue;
    const id = String(f.Lead);
    if (!noShow[id] || f.Start > noShow[id].fields.Start) noShow[id] = a;
  }
  for (const [id, a] of Object.entries(noShow)) {
    if (!leads[id] || futureBooked.has(id)) continue;          // already rebooked: nothing to chase
    push({
      kind: 'rebook', template: 'noshow_rebook', ...person(id),
      flag_table: 'Appointments', flag_row_id: a.id, flag_column: 'Rebook_Sent', flag_value: a.fields.Rebook_Sent || null,
      booking_uid: a.fields.Booking_UID || `row ${a.id}`, service: String(a.fields.Service || ''), appt_start: a.fields.Start,
    });
  }

  // 2. One follow-up: open leads created `followupAfter` to `lostAfter - 1` days ago, Followup_Sent off, nothing booked.
  const isOpen = (r) => {
    const f = r.fields || {};
    return OPEN.includes(f.Status) && typeof f.Created_At === 'number' && !futureBooked.has(String(r.id));
  };
  const age = (r) => daysAgo(r.fields.Created_At);
  const oldestFirst = (a, b) => a.fields.Created_At - b.fields.Created_At;
  // A5: no day-2 follow-up while a person must answer, the patient wrote in the last 48 h, said not interested / stop, the AI
  // rated the lead cold, or a call-back is planned (Next_Action_At in the future). Without these fields: as before.
  const aiHold = (r) => {
    const f = r.fields || {};
    return hold.has(String(r.id)) || f.Lead_Stage === 'cold' || (typeof f.Next_Action_At === 'number' && f.Next_Action_At * 1000 > nowMs);
  };
  leadRows
    .filter((r) => isOpen(r) && !r.fields.Followup_Sent && age(r) >= followupAfter && age(r) < lostAfter && !aiHold(r))
    .sort(oldestFirst)
    .slice(0, maxFollowups)
    .forEach((r) => push({
      kind: 'followup', template: 'followup_day2', ...person(String(r.id)),
      flag_table: 'LEADS', flag_row_id: r.id, flag_column: 'Followup_Sent', flag_value: r.fields.Followup_Sent ? 1 : null,
    }));

  // 3. Mark Lost: open leads `lostAfter`+ days old, unless staff have a call-back planned (Next_Action_At in the future).
  if (cfg.mark_lost !== false) {
    leadRows
      .filter((r) => isOpen(r) && age(r) >= lostAfter && !(typeof r.fields.Next_Action_At === 'number' && r.fields.Next_Action_At * 1000 > nowMs))
      .sort(oldestFirst)
      .slice(0, maxLost)
      .forEach((r) => push({ kind: 'lost', ...person(String(r.id)) }));
  }
});
return out;

// Pasted from n8n/snippets/normalize-phone.js and n8n/snippets/send-guard.js - keep identical.
function normalizeIndianPhone(raw) {
  if (raw === null || raw === undefined) return { phone: null, valid: false };
  let digits = String(raw).replace(/\D/g, '');          // keep digits only
  if (digits.startsWith('0091')) digits = digits.slice(4);
  else if (digits.length === 12 && digits.startsWith('91')) digits = digits.slice(2);
  else if (digits.length === 11 && digits.startsWith('0')) digits = digits.slice(1);
  const valid = /^[6-9]\d{9}$/.test(digits);            // Indian mobiles start 6-9
  return { phone: valid ? `+91${digits}` : null, valid };
}

function isTestMode(value) {
  const v = String(value === null || value === undefined ? '' : value).trim().toLowerCase();
  return !['false', '0', 'no', 'off'].includes(v);   // anything else, including a missing row, means ON (fail safe)
}

function inQuietHours(nowMs) {
  if (!Number.isFinite(nowMs)) return true;           // no clock, no send
  const hourIST = new Date(nowMs + 5.5 * 3600 * 1000).getUTCHours();
  return hourIST >= 21 || hourIST < 8;
}

function decideSend(i) {
  const testMode = isTestMode(i.test_mode);
  const skip = (reason) => ({ send: false, to: null, reason, test_mode: testMode });

  if (i.flag_value) return skip('already sent');
  if (i.opted_out) return skip('opted out');
  if (i.kind !== 'transactional' && i.automation_paused) return skip('automation paused');
  if (inQuietHours(i.now_ms)) return skip('quiet hours');

  const to = testMode ? i.test_phone : i.patient_phone;
  if (!to) return skip(testMode ? 'test mode on but TEST_PHONE is missing or invalid' : 'no valid patient phone');
  return { send: true, to, reason: testMode ? 'test mode: sent to TEST_PHONE' : 'ok', test_mode: testMode };
}

  const { phone: patient_phone } = normalizeIndianPhone($json.lead_phone);
  const { phone: test_phone } = normalizeIndianPhone($json.test_phone);
  const decision = decideSend({
    kind: 'marketing',                 // follow-ups: Automation_Paused stops them (guide, section 6)
    flag_value: $json.flag_value,
    opted_out: $json.opted_out,
    automation_paused: $json.automation_paused,
    patient_phone,
    test_mode: $json.test_mode,
    test_phone,
    now_ms: Date.now(),
  });
  return { json: { ...$json, decision, send: decision.send } };

const now = Math.floor(Date.now() / 1000);
const log = (record) => ({ Workflow: 'W6-followups', Record: record, Outcome: 'ok', Error: '', At: now });
if ($json.kind === 'lost') {
  return {
    json: {
      ...$json,
      patch_table: 'LEADS',
      patch: { records: [{ id: $json.lead_row_id, fields: { Status: 'Lost', Lost_Reason: 'No response' } }] },
      log: log(`${$json.lead_id} (lost: no response)`),
    },
  };
}
// after a real send: tick the flag on the row the message was about (rule 4: right after the send)
const value = $json.flag_column === 'Rebook_Sent' ? now : true;   // Rebook_Sent is a DateTime, Followup_Sent a Toggle
const record = $json.kind === 'rebook' ? `${$json.booking_uid} (rebook) ${$json.lead_id}` : `${$json.lead_id} (followup)`;
return {
  json: {
    ...$json,
    patch_table: $json.flag_table,
    patch: { records: [{ id: $json.flag_row_id, fields: { [$json.flag_column]: value } }] },
    log: log(record),
  },
};

const item = $json;

const name = item.lead_name || 'there';
const clinic = item.clinic_name || 'Clinic';
const booking_link = item.booking_link || '';

let template;
let template_params;
let message_text;

if (item.kind === 'rebook') {
  template = 'noshow_rebook';

  const t = new Date(Number(item.appt_start) * 1000);

  const date = t.toLocaleDateString('en-IN', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    timeZone: 'Asia/Kolkata',
  });

  const service = item.service || 'appointment';

  template_params = {
    name,
    service,
    clinic_name: clinic,
    date,
    booking_link,
  };

  message_text =
    `Hi ${name}, we missed you at your ${service} appointment at ${clinic} on ${date}. ` +
    `You can book another time here: ${booking_link}`;

} else {
  template = 'hello_world';

  template_params = {};

  message_text =
    `Hi ${name}, thanks for contacting ${clinic}. ` +
    `Would you like to book your visit? ${booking_link}`;
}

return {
  json: {
    ...item,

    audience: 'patient',
    source_workflow: 'W6-followups',

    template,
    template_params,
    message_text,

    lead_phone:
      item.lead_phone ||
      item.patient_phone ||
      '',

    wa_phone_number_id:
      item.wa_phone_number_id ||
      '',

    decision: item.decision || {
      send: Boolean(item.send),
      to: item.send_to || item.test_phone || item.lead_phone || '',
      reason: 'W6 follow-up',
      test_mode: Boolean(item.test_mode),
    },

    send: Boolean(item.send),
  },
};

const ex = $json.execution || {};
const err = ex.error || {};
const wfName = ($json.workflow || {}).name || 'unknown workflow';
const step = ex.lastNodeExecuted || (err.node && err.node.name) || 'unknown step';
const throttleMs = (Number($json.throttle_minutes) || 10) * 60000;

// Keep patient data and secrets out of the alert: mask long digit runs (phones) and token-like text, then trim.
const safe = (s, max) =>
  String(s === undefined || s === null ? '' : s)
    .replace(/bearer\s+\S+/gi, 'bearer [hidden]')
    .replace(/(token|api[_-]?key|secret|authorization|password)[\s:=]+\S+/gi, '$1 [hidden]')
    .replace(/\+?\d[\d\s-]{7,}\d/g, '[number]')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, max);
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');   // Telegram parse_mode=HTML

// Throttle: the same failure (workflow + step + message) alerts at most once per throttle window.
const store = $getWorkflowStaticData('global');
store.recent = store.recent || {};
const now = Date.now();
for (const k of Object.keys(store.recent)) if (now - store.recent[k].at > 24 * 3600 * 1000) delete store.recent[k];
const old = Object.keys(store.recent).sort((a, b) => store.recent[a].at - store.recent[b].at);
old.slice(0, Math.max(0, old.length - 49)).forEach((k) => delete store.recent[k]);   // at most 50 entries once this one is added

const key = `${wfName}|${step}|${safe(err.message, 80)}`;
const prev = store.recent[key];
let send = true;
let held = 0;
if (prev && now - prev.at < throttleMs) {
  prev.held = (prev.held || 0) + 1;
  send = false;
} else {
  held = prev ? prev.held || 0 : 0;
  store.recent[key] = { at: now, held: 0 };
}

const when = new Date(now + 5.5 * 3600 * 1000).toISOString().replace('T', ' ').slice(0, 16) + ' IST';
const lines = [
  '<b>n8n workflow failed</b>',
  `Workflow: ${esc(safe(wfName, 100))}`,
  `Step: ${esc(safe(step, 100))}`,
  `Error: ${esc(safe(err.message || 'no message', 300))}`,
  `Time: ${when}`,
];
if (ex.url) lines.push(`Execution: ${esc(String(ex.url).slice(0, 300))}`);
if (held > 0) lines.push(`(${held} similar alert${held === 1 ? '' : 's'} held back since the last one)`);

return { json: { telegram_chat_id: $json.telegram_chat_id, alert_text: lines.join('\n'), send, workflow_name: wfName, step } };

// Manual test: edit these values, then click "Execute workflow" (the Manual test trigger).
// 1st test: hello_world (Meta's sample template, no variables) to your own phone.
// The number must be in the allowlist (Config node) AND in Meta's allowed list for the test number.
return [{
  json: {
    source_workflow: 'W12-manual-test',
    audience: 'staff',                       // 'patient' also writes to the Grist Inbox (Conversations + Messages)
    template: 'hello_world',
    template_params: {},
    message_text: 'W12 manual test (hello_world)',
    wa_phone_number_id: '123456789012345',   // Meta > WhatsApp > API Setup > Phone number ID
    decision: { send: true, to: 'PASTE_YOUR_TEST_NUMBER', reason: 'manual test', test_mode: true },
    grist_base_url: 'http://grist:8484',     // only used when audience = 'patient'
    doc_id: '2YsFnXyZMLbQ',
    lead_row_id: null,
    lead_phone: null,
  },
}];

// Pasted from n8n/snippets/normalize-phone.js, send-guard.js (inQuietHours) and wa-send.js - keep identical.
function normalizeIndianPhone(raw) {
  if (raw === null || raw === undefined) return { phone: null, valid: false };
  let digits = String(raw).replace(/\D/g, '');          // keep digits only
  if (digits.startsWith('0091')) digits = digits.slice(4);
  else if (digits.length === 12 && digits.startsWith('91')) digits = digits.slice(2);
  else if (digits.length === 11 && digits.startsWith('0')) digits = digits.slice(1);
  const valid = /^[6-9]\d{9}$/.test(digits);            // Indian mobiles start 6-9
  return { phone: valid ? `+91${digits}` : null, valid };
}

function inQuietHours(nowMs) {
  if (!Number.isFinite(nowMs)) return true;           // no clock, no send
  const hourIST = new Date(nowMs + 5.5 * 3600 * 1000).getUTCHours();
  return hourIST >= 21 || hourIST < 8;
}

const WA_TEMPLATES = {
  hello_world: { language: 'en_US', params: [] },          // Meta's sample template on the test number
  booking_confirmation: { params: ['name', 'service', 'clinic_name', 'date', 'time'] },
  reminder_24h: { params: ['name', 'service', 'clinic_name', 'date', 'time'] },
  reminder_2h: { params: ['name', 'service', 'clinic_name', 'time'] },
  noshow_rebook: { params: ['name', 'service', 'clinic_name', 'date', 'booking_link'] },
  followup_day2: { params: ['name', 'clinic_name', 'booking_link'] },
  new_lead_staff_alert: { params: ['clinic_name', 'lead_name', 'lead_phone', { key: 'enquiry', fallback: '(no message)' }] },
  lead_escalation: { params: ['clinic_name', 'lead_name', 'lead_phone', 'waiting_minutes'] },
  human_handoff_alert: { params: ['clinic_name', 'lead_name', 'lead_phone', { key: 'reason', fallback: '(see the Grist inbox)' }] },
};

// Free-text replies (message_type 'text', from W13) are only allowed inside WhatsApp's 24-hour customer-service
// window, i.e. within 24 h of the patient's last message (last_inbound_at). A 5-minute margin keeps clock drift safe.
const WA_TEXT_WINDOW_MS = 24 * 3600 * 1000 - 5 * 60 * 1000;

// Short hints for the Meta error codes we are most likely to meet (shown in send_error).
const WA_HINTS = {
  190: 'access token invalid or expired - put a permanent System User token in the "WhatsApp Cloud API" credential',
  10: 'token lacks permission - give the System User whatsapp_business_messaging',
  200: 'token lacks permission - give the System User whatsapp_business_messaging',
  100: 'invalid parameter - check wa_phone_number_id and the template',
  131030: "recipient is not in the test number's allowed list - add it in Meta > WhatsApp > API Setup",
  131026: 'message undeliverable (number not on WhatsApp?)',
  131047: 'outside the 24h window - only templates can be sent',
  131056: 'too many messages to this number - try later',
  130429: 'rate limit hit - try later',
  132000: 'number of template variables does not match the approved template',
  132001: 'template not found in this language - check the name and language code',
  132005: 'template text too long after filling the variables',
  132007: 'template content policy violation',
  132012: 'template variable format does not match',
  133010: 'phone number not registered with the Cloud API',
  131031: 'WhatsApp account locked',
  368: 'temporarily blocked for policy violations',
};

// Meta: a variable may not contain new-lines, tabs or runs of spaces.
function waCleanParam(v) {
  return String(v === null || v === undefined ? '' : v).replace(/\s+/g, ' ').trim().slice(0, 250);
}

// Decide whether to call Meta, and build the request. Never throws.
// input: the caller's item (decision, template, template_params, wa_phone_number_id, ...); cfg: W12 Config.
function waPrepare(input, cfg, nowMs, h) {
  const stop = (send_status, send_error) => ({ call_meta: false, send_status, send_error });
  const d = input && input.decision;
  if (!d || d.send !== true) return stop('not_requested', d && d.reason ? `guard said no: ${d.reason}` : 'no send decision from the caller');

  const mode = String(cfg.send_mode || '').trim().toLowerCase();
  if (mode !== 'allowlist' && mode !== 'live') return stop('blocked', `W12 send_mode is "${cfg.send_mode}" - only "allowlist" or "live" send`);

  // 1. Is the message itself sendable? (reported even while testing in allowlist mode or at night)
  const to = h.normalizeIndianPhone(d.to).phone;
  if (!to) return stop('invalid', 'decision.to is not a valid Indian mobile number');
  const version = String(cfg.graph_api_version || '').trim();
  if (!/^v\d+\.\d+$/.test(version)) return stop('invalid', 'graph_api_version is not set in the W12 Config node (e.g. v23.0 - copy it from Meta API Setup)');
  const phoneId = String(input.wa_phone_number_id || '').trim();
  if (!/^\d{5,25}$/.test(phoneId)) return stop('invalid', 'wa_phone_number_id is missing or not a number (Agency Registry > Clinics > WA_Phone_Number_ID)');
  const isText = input.message_type === 'text';
  let tpl = null;
  let textBody = '';
  const params = [];
  if (isText) {
    textBody = String(input.text_body === null || input.text_body === undefined ? '' : input.text_body).replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '').trim().slice(0, 4096);
    if (!textBody) return stop('invalid', 'text message: text_body is empty');
    const last = Number(input.last_inbound_at);
    if (!Number.isFinite(last) || last <= 0) return stop('invalid', 'text message: last_inbound_at (the patient\'s last message, epoch seconds) is missing');
    if (nowMs - last * 1000 > WA_TEXT_WINDOW_MS) return stop('blocked', 'outside the 24-hour WhatsApp window: only an approved template may be sent');
  } else {
    tpl = WA_TEMPLATES[input.template];
    if (!tpl) return stop('invalid', `unknown template "${input.template}" - add it to WA_TEMPLATES in W12`);
    const values = input.template_params || {};
    for (const spec of tpl.params) {
      const key = typeof spec === 'string' ? spec : spec.key;
      let v = waCleanParam(values[key]);
      if (!v && typeof spec === 'object') v = spec.fallback;
      if (!v) return stop('invalid', `template ${input.template}: variable "${key}" is empty`);
      params.push(v);
    }
  }

  // 2. May it go out now, to this number?
  if (mode === 'allowlist') {
    const allowed = String(cfg.allowlist || '').split(/[,;]+/).map((x) => h.normalizeIndianPhone(x).phone).filter(Boolean);
    if (!allowed.includes(to)) return stop('blocked', `${to} is not in the W12 allowlist (send_mode = allowlist)`);
  }
  if (h.inQuietHours(nowMs)) return stop('blocked', 'quiet hours (21:00-08:00 IST)');

  if (isText) {
    return {
      call_meta: true,
      send_status: 'pending',
      send_error: '',
      to,
      meta_url: `https://graph.facebook.com/${version}/${phoneId}/messages`,
      meta_request: { messaging_product: 'whatsapp', recipient_type: 'individual', to: to.slice(1), type: 'text', text: { preview_url: /https?:\/\//i.test(textBody), body: textBody } },
    };
  }
  const template = { name: input.template, language: { code: String(input.template_language || tpl.language || cfg.default_language || 'en') } };
  if (params.length) template.components = [{ type: 'body', parameters: params.map((text) => ({ type: 'text', text })) }];
  return {
    call_meta: true,
    send_status: 'pending',
    send_error: '',
    to,
    meta_url: `https://graph.facebook.com/${version}/${phoneId}/messages`,
    meta_request: { messaging_product: 'whatsapp', recipient_type: 'individual', to: to.slice(1), type: 'template', template },
  };
}

// Turn the HTTP node output (fullResponse + neverError, or a "continue on error" item) into a result.
//   accepted  Meta returned a message id                  -> sent: true
//   rejected  Meta refused, or the request never left     -> sent: false (safe to try again later)
//   uncertain the request left but no clear answer came   -> sent: cfg.uncertain_counts_as_sent (default true:
//             rather miss one message than send it twice, CLAUDE.md rule 4)
function waClassify(resp, cfg) {
  const uncertainSent = cfg.uncertain_counts_as_sent !== false;
  const result = (send_status, extra) => Object.assign({
    send_status,
    sent: send_status === 'accepted' || (send_status === 'uncertain' && uncertainSent),
    wa_message_id: '',
    send_error: '',
    send_error_code: null,
    send_http_status: null,
  }, extra);

  if (resp && typeof resp.statusCode === 'number') {
    let body = resp.body;
    if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
    body = body || {};
    const id = body.messages && body.messages[0] && body.messages[0].id;
    if (resp.statusCode >= 200 && resp.statusCode < 300) {
      return id
        ? result('accepted', { wa_message_id: String(id), send_http_status: resp.statusCode })
        : result('uncertain', { send_error: 'Meta answered without a message id', send_http_status: resp.statusCode });
    }
    const e = body.error || {};
    const code = e.code !== undefined && e.code !== null ? Number(e.code) : null;
    const detail = (e.error_data && e.error_data.details) || e.message || `HTTP ${resp.statusCode}`;
    const hint = code !== null && WA_HINTS[code] ? ` (${WA_HINTS[code]})` : '';
    return result('rejected', { send_error_code: code, send_http_status: resp.statusCode, send_error: `${code !== null ? code + ': ' : ''}${detail}${hint}`.slice(0, 500) });
  }

  // n8n's "continue on error" item: { error: '...' } or { error: { message, description, code, ... } }. n8n also
  // rewrites network errors into friendly text, so match both the raw codes and n8n's wording.
  const err = resp && resp.error;
  const msg = String((err && (err.message || err.description)) || (typeof err === 'string' ? err : '') || 'no reply from Meta');
  const haystack = typeof err === 'string' ? err : JSON.stringify(err || {});
  if (/ENOTFOUND|EAI_AGAIN|ECONNREFUSED|EHOSTUNREACH|ENETUNREACH|certificate|self[- ]signed|refused the connection|DNS server returned an error/i.test(haystack)) {
    return result('rejected', { send_error: `not sent - could not reach Meta: ${msg}`.slice(0, 500) });
  }
  return result('uncertain', { send_error: `no clear answer from Meta (it may or may not have been sent): ${msg}`.slice(0, 500) });
}

// Should this send be written to the Grist Inbox (Conversations + Messages)? Only patient messages that
// actually reached the point of calling Meta. The conversation is the PATIENT's (lead_phone), even when
// TEST_MODE sent the message to TEST_PHONE.
function waInboxPlan(input, cfg, res, h) {
  const patient_phone = h.normalizeIndianPhone(input.lead_phone || input.patient_phone).phone;
  const attempted = ['accepted', 'uncertain', 'rejected'].includes(res.send_status);
  const log = cfg.log_to_inbox !== false && input.audience === 'patient' && attempted && !!patient_phone && !!input.grist_base_url && !!input.doc_id;
  return { log, patient_phone };
}

// The Messages row. Send stays false: W10 sends rows whose Send is ticked, and this one is already out.
function waInboxRow(input, res, nowSec) {
  const d = input.decision || {};
  const via = d.test_mode ? ` (TEST_MODE: sent to ${d.to})` : '';
  return {
    Direction: 'Out',
    Body: String(input.message_text || input.text_body || `[template ${input.template}]`).slice(0, 2000),
    Template: input.message_type === 'text' ? '' : String(input.template || ''),
    Sent_By: `${input.source_workflow || 'W12'}${via}`.slice(0, 200),
    WA_Message_ID: res.wa_message_id || '',
    Status: res.send_status === 'rejected' ? 'failed' : 'queued',
    Send: false,
    Created_At: nowSec,
  };
}

  const cfg = {
    send_mode: $json.w12_send_mode,
    allowlist: $json.w12_allowlist,
    graph_api_version: $json.w12_graph_api_version,
    default_language: $json.w12_default_language,
    uncertain_counts_as_sent: $json.w12_uncertain_counts_as_sent,
    log_to_inbox: $json.w12_log_to_inbox,
  };
  const input = {};
  for (const [k, v] of Object.entries($json)) if (!k.startsWith('w12_')) input[k] = v;   // the caller's item, untouched
  const prep = waPrepare(
  input,
  cfg,
  Date.now(),
